//! Decoder for assembled bytecode.
//!
//! The `OpCode` and `Instruction` enums, the per-opcode field decoder and the
//! operand / jump target visitors are generated by build.rs from
//! interpreter.flap. The input is the exact byte stream the interpreter
//! executes: operands are flat slot indices, labels are absolute byte offsets.

include!(concat!(env!("OUT_DIR"), "/decoder_generated.rs"));

/// A frame slot, as a flat index into the interpreter's
/// `[registers | locals | constants | arguments]` value array.
///
/// See `FrameLayout` for how to classify an index.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Operand(u32);

impl Operand {
    /// The encoding of an absent `Optional<Operand>`.
    pub const INVALID: u32 = 0xFFFF_FFFF;

    pub fn from_raw(raw: u32) -> Self {
        Self(raw)
    }

    pub fn optional_from_raw(raw: u32) -> Option<Self> {
        if raw == Self::INVALID { None } else { Some(Self(raw)) }
    }

    /// The flat slot index, as the bytecode encodes it.
    pub fn raw(self) -> u32 {
        self.0
    }
}

/// Whether an instruction reads an operand, writes it, or both.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OperandRole {
    In,
    Out,
    InOut,
}

impl OperandRole {
    pub fn is_read(self) -> bool {
        matches!(self, OperandRole::In | OperandRole::InOut)
    }

    pub fn is_written(self) -> bool {
        matches!(self, OperandRole::Out | OperandRole::InOut)
    }
}

/// A bytecode offset (absolute, from the start of the executable's bytecode).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Label(pub u32);

/// Index into the executable's identifier table.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct IdentifierTableIndex(pub u32);

impl IdentifierTableIndex {
    pub const INVALID: u32 = 0xFFFF_FFFF;

    pub fn optional_from_raw(raw: u32) -> Option<Self> {
        if raw == Self::INVALID { None } else { Some(Self(raw)) }
    }
}

/// Index into the executable's property key table.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PropertyKeyTableIndex(pub u32);

/// Index into the executable's string table.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StringTableIndex(pub u32);

impl StringTableIndex {
    pub const INVALID: u32 = 0xFFFF_FFFF;

    pub fn optional_from_raw(raw: u32) -> Option<Self> {
        if raw == Self::INVALID { None } else { Some(Self(raw)) }
    }
}

/// Index into the executable's regex table.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RegexTableIndex(pub u32);

/// Environment coordinate used by the binding instructions.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EnvironmentCoordinate {
    pub hops: u32,
    pub index: u32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DecodeErrorKind {
    UnknownOpcode,
    TruncatedInstruction,
    InvalidLength,
}

/// Why the instruction at `pc` could not be decoded.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct DecodeError {
    pub pc: u32,
    pub kind: DecodeErrorKind,
}

/// How a slow path that takes an instruction's `Op` record receives its
/// operands, following Flap's `SlowPathLayout`. The record (`Op::Values`) has
/// one value per scalar operand field, in field order, followed by the values
/// of the operand array.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SlowPathAbi {
    /// `AsmSlowPathResult f(VM*, u32 pc, Op const*, Value input...)`: the
    /// inputs are passed by value and the single output, if any, comes back as
    /// the second return word.
    Scalar,
    /// `i64 f(VM*, u32 pc, Op const*, Op::Values& outputs, Value input...)`:
    /// inputs (and input/outputs) by value, outputs written to the record.
    ScalarInputs,
    /// `i64 f(VM*, u32 pc, Op const*, Op::Values& values)`: everything in the
    /// record, including the operand array.
    Record,
}

/// One scalar operand field of an instruction, as seen by its slow path.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SlowPathField {
    /// Byte offset of the operand within the instruction.
    pub instruction_offset: u32,
    pub role: OperandRole,
    /// Whether the operand is an `Optional<Operand>`; absent ones read as the empty value.
    pub optional: bool,
}

/// The operand array of an instruction, as seen by its slow path.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SlowPathArray {
    /// Byte offset of the first operand of the array within the instruction.
    pub instruction_offset: u32,
    /// Byte offset of the u32 element count within the instruction.
    pub count_offset: u32,
    pub optional: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SlowPathLayout {
    pub abi: SlowPathAbi,
    pub fields: &'static [SlowPathField],
    pub array: Option<SlowPathArray>,
}

/// The interpreter feedback slots one instruction records into, one index
/// space per feedback kind (see `Libraries/LibJS/Rust/src/layout/feedback.rs`).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct FeedbackSlots {
    pub arith: Option<u16>,
    pub value: Option<u16>,
    pub call: Option<u16>,
    pub keyed: Option<u16>,
}

/// One decoded instruction and where it lives in the bytecode.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DecodedInstruction {
    /// Byte offset of the instruction.
    pub pc: u32,
    /// Encoded length in bytes; the next instruction starts at `pc + length`.
    pub length: u32,
    pub strict: bool,
    pub instruction: Instruction,
}

impl DecodedInstruction {
    pub fn next_pc(&self) -> u32 {
        self.pc + self.length
    }
}

fn read_u16(bytes: &[u8], at: usize) -> u16 {
    u16::from_ne_bytes(bytes[at..at + 2].try_into().unwrap())
}

fn read_u32(bytes: &[u8], at: usize) -> u32 {
    u32::from_ne_bytes(bytes[at..at + 4].try_into().unwrap())
}

fn read_u64(bytes: &[u8], at: usize) -> u64 {
    u64::from_ne_bytes(bytes[at..at + 8].try_into().unwrap())
}

/// Decodes the instruction starting at byte offset `pc`.
pub fn decode_instruction(bytes: &[u8], pc: u32) -> Result<DecodedInstruction, DecodeError> {
    let error = |kind| DecodeError { pc, kind };
    let at = pc as usize;
    // The two byte header holds the opcode and the strict mode flag.
    if at.checked_add(2).is_none_or(|header_end| header_end > bytes.len()) {
        return Err(error(DecodeErrorKind::TruncatedInstruction));
    }
    let opcode = bytes[at];
    let strict = bytes[at + 1] != 0;
    let length = instruction_length_from_bytes(opcode, bytes, at).map_err(error)?;
    if length == 0 || at + length > bytes.len() {
        return Err(error(DecodeErrorKind::TruncatedInstruction));
    }
    let length_u32 = u32::try_from(length).map_err(|_| error(DecodeErrorKind::InvalidLength))?;
    let instruction = decode_fields(opcode, bytes, at, length).map_err(error)?;
    Ok(DecodedInstruction {
        pc,
        length: length_u32,
        strict,
        instruction,
    })
}

/// Decodes a whole instruction stream.
pub fn decode_all(bytes: &[u8]) -> Result<Vec<DecodedInstruction>, DecodeError> {
    let end = u32::try_from(bytes.len()).map_err(|_| DecodeError {
        pc: 0,
        kind: DecodeErrorKind::InvalidLength,
    })?;
    let mut instructions = Vec::new();
    let mut pc = 0;
    while pc < end {
        let instruction = decode_instruction(bytes, pc)?;
        pc = instruction.next_pc();
        instructions.push(instruction);
    }
    Ok(instructions)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn operand(index: u32) -> Operand {
        Operand::from_raw(index)
    }

    fn operands_with_roles(instruction: &Instruction) -> Vec<(u32, OperandRole)> {
        let mut operands = Vec::new();
        instruction.for_each_operand(|operand, role| operands.push((operand.raw(), role)));
        operands
    }

    fn jump_targets(instruction: &Instruction) -> Vec<u32> {
        let mut targets = Vec::new();
        instruction.for_each_jump_target(|label| targets.push(label.0));
        targets
    }

    #[test]
    fn decodes_hand_assembled_mov() {
        let mut bytes = vec![OpCode::Mov as u8, 1, 0, 0];
        bytes.extend(7u32.to_ne_bytes()); // dst
        bytes.extend(12u32.to_ne_bytes()); // src
        bytes.extend([0; 4]); // Padding to the 8 byte instruction alignment.

        let decoded = decode_instruction(&bytes, 0).unwrap();
        assert_eq!(decoded.pc, 0);
        assert_eq!(decoded.length, 16);
        assert!(decoded.strict);
        assert_eq!(
            decoded.instruction,
            Instruction::Mov {
                dst: operand(7),
                src: operand(12)
            }
        );
        assert_eq!(decoded.instruction.opcode(), OpCode::Mov);
        assert_eq!(
            operands_with_roles(&decoded.instruction),
            [(7, OperandRole::Out), (12, OperandRole::In)]
        );
        assert!(!decoded.instruction.is_terminator());
        assert!(OpCode::Mov.can_fall_through());
    }

    #[test]
    fn decodes_hand_assembled_jump_if() {
        let mut bytes = vec![0; 16];
        let mut jump = vec![OpCode::JumpIf as u8, 0, 0, 0];
        jump.extend(5u32.to_ne_bytes()); // condition
        jump.extend(32u32.to_ne_bytes()); // true_target
        jump.extend(48u32.to_ne_bytes()); // false_target
        bytes.extend(jump);

        let decoded = decode_instruction(&bytes, 16).unwrap();
        assert_eq!(decoded.pc, 16);
        assert_eq!(decoded.length, 16);
        assert_eq!(decoded.next_pc(), 32);
        assert!(!decoded.strict);
        assert_eq!(
            decoded.instruction,
            Instruction::JumpIf {
                condition: operand(5),
                true_target: Label(32),
                false_target: Label(48)
            }
        );
        assert_eq!(jump_targets(&decoded.instruction), [32, 48]);
        assert_eq!(operands_with_roles(&decoded.instruction), [(5, OperandRole::In)]);
        assert!(decoded.instruction.is_terminator());
        assert!(OpCode::JumpIf.is_terminator());
        assert!(!OpCode::JumpIf.can_fall_through());
        assert!(OpCode::JumpTrue.is_terminator());
        assert!(OpCode::JumpTrue.can_fall_through());
        assert!(!OpCode::Return.can_fall_through());
    }

    #[test]
    fn decodes_variable_length_call() {
        let call = Instruction::Call {
            value_feedback: 0,
            call_feedback: 0,
            dst: operand(5),
            callee: operand(6),
            this_value: operand(7),
            argument_count: 3,
            expression_string: Some(StringTableIndex(9)),
            arguments: vec![operand(8), operand(20), operand(21)],
        };
        let mut bytes = Vec::new();
        call.encode(true, &mut bytes);
        assert_eq!(bytes.len() % 8, 0);

        let decoded = decode_instruction(&bytes, 0).unwrap();
        assert_eq!(decoded.length as usize, bytes.len());
        assert_eq!(decoded.length as usize, call.encoded_size());
        assert_eq!(decoded.instruction, call);
        assert_eq!(
            operands_with_roles(&decoded.instruction),
            [
                (5, OperandRole::Out),
                (6, OperandRole::In),
                (7, OperandRole::In),
                (8, OperandRole::In),
                (20, OperandRole::In),
                (21, OperandRole::In),
            ]
        );
        assert!(!decoded.instruction.is_terminator());
    }

    #[test]
    fn round_trips_a_stream_of_instructions() {
        let instructions = [
            Instruction::Enter,
            Instruction::NewPrimitiveArray {
                dst: operand(5),
                element_count: 2,
                elements: vec![0x7ff8_0000_0000_0001, 42],
            },
            Instruction::NewClass {
                dst: operand(6),
                super_class: None,
                class_environment: operand(7),
                class_blueprint_index: 1,
                lhs_name: Some(IdentifierTableIndex(4)),
                element_keys_count: 3,
                element_keys: vec![Some(operand(8)), None, Some(operand(9))],
            },
            Instruction::GetBinding {
                value_feedback: 0,
                dst: operand(5),
                identifier: IdentifierTableIndex(3),
                cache: EnvironmentCoordinate { hops: 1, index: 2 },
            },
            Instruction::CreateArguments {
                dst: None,
                kind: 1,
                is_immutable: true,
                creates_parameter_bindings: false,
            },
            Instruction::AddRhsInt32 {
                arith_feedback: 0,
                dst: operand(5),
                lhs: operand(6),
                rhs: -5,
            },
            Instruction::Mov2 {
                c0_dst: operand(5),
                c0_src: operand(6),
                c1_dst: operand(7),
                c1_src: operand(5),
            },
            Instruction::PostfixIncrement {
                arith_feedback: 0,
                dst: operand(5),
                src: operand(6),
            },
            Instruction::Yield {
                continuation_label: Some(Label(0)),
                value: operand(5),
            },
            Instruction::Yield {
                continuation_label: None,
                value: operand(5),
            },
        ];
        let mut bytes = Vec::new();
        for (index, instruction) in instructions.iter().enumerate() {
            instruction.encode(index % 2 == 0, &mut bytes);
        }

        let decoded = decode_all(&bytes).unwrap();
        assert_eq!(decoded.len(), instructions.len());
        let mut pc = 0;
        for (index, (decoded, instruction)) in decoded.iter().zip(&instructions).enumerate() {
            assert_eq!(&decoded.instruction, instruction);
            assert_eq!(decoded.pc, pc);
            assert_eq!(decoded.strict, index % 2 == 0);
            pc += u32::try_from(instruction.encoded_size()).unwrap();
        }

        assert_eq!(
            operands_with_roles(&decoded[2].instruction),
            [
                (6, OperandRole::Out),
                (7, OperandRole::In),
                (8, OperandRole::In),
                (9, OperandRole::In)
            ]
        );
        assert!(operands_with_roles(&decoded[4].instruction).is_empty());
        assert_eq!(
            operands_with_roles(&decoded[6].instruction),
            [
                (5, OperandRole::Out),
                (6, OperandRole::In),
                (7, OperandRole::Out),
                (5, OperandRole::In)
            ]
        );
        assert_eq!(
            operands_with_roles(&decoded[7].instruction),
            [(5, OperandRole::Out), (6, OperandRole::InOut)]
        );
        assert_eq!(jump_targets(&decoded[8].instruction), [0]);
        assert!(jump_targets(&decoded[9].instruction).is_empty());
        assert!(decoded[9].instruction.is_terminator());
    }

    #[test]
    fn rejects_malformed_instructions() {
        let error = |bytes: &[u8]| decode_instruction(bytes, 0).unwrap_err().kind;

        assert_eq!(error(&[]), DecodeErrorKind::TruncatedInstruction);
        assert_eq!(error(&[u8::MAX, 0]), DecodeErrorKind::UnknownOpcode);

        let mut mov = Vec::new();
        Instruction::Mov {
            dst: operand(5),
            src: operand(6),
        }
        .encode(false, &mut mov);
        assert_eq!(error(&mov[..8]), DecodeErrorKind::TruncatedInstruction);

        let mut call = Vec::new();
        Instruction::Call {
            value_feedback: 0,
            call_feedback: 0,
            dst: operand(5),
            callee: operand(6),
            this_value: operand(7),
            argument_count: 1,
            expression_string: None,
            arguments: vec![operand(8)],
        }
        .encode(false, &mut call);
        // Call's layout: header, value and call feedback slots, m_length at 8, dst, callee, this_value,
        // argument_count at 24.
        let mut short_length = call.clone();
        short_length[8..12].copy_from_slice(&4u32.to_ne_bytes());
        assert_eq!(error(&short_length), DecodeErrorKind::InvalidLength);
        let mut too_many_arguments = call.clone();
        too_many_arguments[24..28].copy_from_slice(&100u32.to_ne_bytes());
        assert_eq!(error(&too_many_arguments), DecodeErrorKind::InvalidLength);
        assert_eq!(error(&call[..call.len() - 8]), DecodeErrorKind::TruncatedInstruction);

        let mut stream = mov.clone();
        stream.extend(&mov[..8]);
        assert_eq!(
            decode_all(&stream).unwrap_err(),
            DecodeError {
                pc: 16,
                kind: DecodeErrorKind::TruncatedInstruction
            }
        );
    }
}
